account = onchainTable(
    "account",
    (p) => ({
      chainId: p.integer().notNull(),
      address: p.hex().notNull(),
      balance: p.bigint(),
    }),
    (table) => ({
      pk: primaryKey({ columns: [table.chainId, table.address] }),
    }),
  )

